163	    /**
164	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
165	     * space, then the national digits (the digits after the country code) grouped in threes from
166	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
167	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
168	     *
169	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
170	     *         {@code null} or not a {@code +} followed by digits
171	     */
172	    public String getTelephoneDisplay() {
173	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
174	            return this.telephone;
175	        }
176	        String digits = this.telephone.substring(1);
177	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
178	        if (digits.length() <= countryCodeLength) {
179	            return this.telephone;
180	        }
181	        String countryCode = digits.substring(0, countryCodeLength);
182	        String national = digits.substring(countryCodeLength);
183	        StringBuilder grouped = new StringBuilder();
184	        for (int i = 0; i < national.length(); i++) {
185	            if (i > 0 && i % 3 == 0) {
186	                grouped.append(' ');
187	            }
188	            grouped.append(national.charAt(i));
189	        }
190	        return "+" + countryCode + " " + grouped;
191	    }
