457	        int sum = 0;
458	        boolean dbl = true;
459	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
460	            char c = this.customerCode.charAt(i);
461	            if (c < '0' || c > '9') {
462	                continue;
463	            }
464	            int d = c - '0';
465	            if (dbl) {
466	                d *= 2;
467	                if (d > 9) {
468	                    d -= 9;
469	                }
470	            }
471	            sum += d;
472	            dbl = !dbl;
473	        }
474	        return (10 - (sum % 10)) % 10;
475	    }
