477	    /**
478	     * The owner's membership points, starting at {@code 0}. The owner gains {@code 2} when
479	     * they carry an email address, {@code 1} when they have no namesakes
480	     * ({@code namesakeCount} is {@code 0}), {@code 2} for a household of {@code 3} or more
481	     * members ({@code householdSize}), and {@code 3} for tenure of at least one elapsed
482	     * fiscal year (the {@code registrationDate}'s fiscal year precedes the current fiscal
483	     * year, the fiscal year starting on 1 July). Because a newly created owner is still in
484	     * the current fiscal year, a new owner can score at most {@code 5} points.
485	     *
486	     * @return the membership points
487	     */
488	    public Integer getMembershipPoints() {
489	        int points = 0;
490	        boolean hasEmail = this.email != null && !this.email.isBlank();
491	        if (hasEmail) {
492	            points += 2;
493	        }
494	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
495	        if (noNamesakes) {
496	            points += 1;
497	        }
498	        if (this.householdSize != null && this.householdSize >= 3) {
499	            points += 2;
500	        }
501	        if (this.registrationDate != null
502	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
503	            points += 3;
504	        }
505	        return points;
506	    }
