508	    /**
509	     * The owner's numeric membership level, from {@code 1} to {@code 4}, derived from the
510	     * {@link #getMembershipPoints() membership points}: {@code 1} for {@code 0-1} points,
511	     * {@code 2} for {@code 2-3} points, {@code 3} for {@code 4-5} points, and {@code 4} for
512	     * {@code 6} or more points. Because a newly created owner has zero tenure, a new owner
513	     * scores at most {@code 5} points and so never exceeds level {@code 3}; level {@code 4}
514	     * is reserved for owners whose tenure spans at least one elapsed fiscal year.
515	     *
516	     * <p>When a {@link #getMembershipLevelCap() membership-level cap} has been assigned the
517	     * points-derived level is capped to it, so an owner admitted into an existing household can never
518	     * exceed one level above their household's highest member.
519	     *
520	     * @return the membership level
521	     */
522	    public Integer getMembershipLevel() {
523	        int level = pointsMembershipLevel();
524	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
525	            return this.membershipLevelCap;
526	        }
527	        return level;
528	    }
