530	    /**
531	     * The membership level derived purely from the {@link #getMembershipPoints() membership points},
532	     * before any {@link #getMembershipLevelCap() household cap} is applied.
533	     *
534	     * @return the uncapped, points-derived membership level
535	     */
536	    private int pointsMembershipLevel() {
537	        int points = getMembershipPoints();
538	        if (points >= 6) {
539	            return 4;
540	        }
541	        if (points >= 4) {
542	            return 3;
543	        }
544	        if (points >= 2) {
545	            return 2;
546	        }
547	        return 1;
548	    }
