578	    /**
579	     * City -> canonical region, the fixed ground truth for deriving locality.
580	     */
581	    private static final Map<String, String> CITY_REGION = Map.of(
582	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
583	
584	    /**
585	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
586	     * deriving locality from the postcode ahead of the city.
587	     */
588	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
589	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
590	
591	    /**
592	     * The owner's locality: the canonical region resolved by the postcode range first
593	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
594	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
595	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
596	     * when the city is not in the table either. The postcode takes precedence so cities that share a
597	     * name are disambiguated by their postcode's region.
598	     *
599	     * @return the canonical region string, or {@code "UNKNOWN"}
600	     */
601	    public String getLocality() {
602	        String byPostcode = regionForPostcode(this.postcode);
603	        if (byPostcode != null) {
604	            return byPostcode;
605	        }
606	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
607	    }
