609	    /**
610	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
611	     * its locality.
612	     */
613	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
614	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
615	
616	    /**
617	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
618	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
619	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
620	     * (e.g. {@code "UNKNOWN"}).
621	     *
622	     * @return the IANA timezone name, or {@code null}
623	     */
624	    public String getTimezone() {
625	        return REGION_TIMEZONE.get(getLocality());
626	    }
