628	    /**
629	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
630	     * absent, not a 4-digit number, or in no known range.
631	     *
632	     * @param postcode the owner's postcode (may be {@code null})
633	     * @return the matching region, or {@code null}
634	     */
635	    private static String regionForPostcode(String postcode) {
636	        if (postcode == null || !postcode.matches("\\d{4}")) {
637	            return null;
638	        }
639	        int value = Integer.parseInt(postcode);
640	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
641	            int[] range = entry.getValue();
642	            if (value >= range[0] && value <= range[1]) {
643	                return entry.getKey();
644	            }
645	        }
646	        return null;
647	    }
