180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
183	        HttpHeaders headers = new HttpHeaders();
184	        String idempotencyKey = currentIdempotencyKey();
185	        if (idempotencyKey != null) {
186	            Integer existingId = idempotentCreates.get(idempotencyKey);
187	            if (existingId != null) {
188	                Owner existing = this.clinicService.findOwnerById(existingId);
189	                if (existing != null) {
190	                    // Repeat of a create already performed under this key: return the original
191	                    // owner with 200 instead of creating a duplicate.
192	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
193	                }
194	            }
195	        }
196	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
197	        LocalDate suppliedDate = owner.getRegistrationDate();
198	        if (suppliedDate != null && suppliedDate.isAfter(LocalDate.now())) {
199	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
200	        }
201	        LocalDate effectiveDate = suppliedDate != null ? suppliedDate : LocalDate.now();
202	        LocalDate registrationDate = toBusinessDay(effectiveDate);
203	        owner.setRegistrationDate(registrationDate);
204	        long createdToday = this.clinicService.findAllOwners().stream()
205	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
206	            .count();
207	        if (createdToday >= 100) {
208	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
209	        }
210	        owner.setBulkSignupWarning(createdToday > 80);
211	        if (!applyAddress(owner)) {
212	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
213	        }
214	        String telephone = toE164(owner.getTelephone());
215	        if (telephone == null) {
216	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
217	        }
218	        owner.setTelephone(telephone);
219	        if (owner.getEmail() != null) {
220	            String email = normalizeEmail(owner.getEmail());
221	            if (!EMAIL_PATTERN.matcher(email).matches()) {
222	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
223	            }
224	            if (isDisposableEmailDomain(email)) {
225	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
226	            }
227	            owner.setEmail(email);
228	        }
229	        if (!isPostcodeValidForCity(owner.getPostcode(), regionForCity(owner.getCity()))) {
230	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
231	        }
232	        String cityKey = householdKey(owner.getCity());
233	        long cityCount = this.clinicService.findAllOwners().stream()
234	            .filter(existing -> existing.getCity() != null
235	                && cityKey.equals(householdKey(existing.getCity())))
236	            .count();
237	        if (cityCount >= 50) {
238	            return new ResponseEntity<>(HttpStatus.CONFLICT);
239	        }
240	        // The household is keyed on (normalized last name, postcode): every owner derives the same
241	        // deterministic householdId from those two fields, so owners sharing them are the same
242	        // household. This computed id is what duplicate detection and the household size below key off.
243	        String householdId = householdId(owner);
244	        owner.setHouseholdId(householdId);
245	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
246	            .filter(existing -> !existing.getDeleted())
247	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
248	            .toList();
249	        owner.setHouseholdSize(householdMembers.size() + 1);
250	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
251	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
252	        // Household-duplicate block: a second owner in an existing household (same computed
253	        // householdId) is rejected as a duplicate unless it is a member we can tell apart. A member is
254	        // admitted when it either declares 'sharesHousehold' or supplies its own email (a distinct
255	        // contact identifying a distinct person); an undistinguished second owner is still a 409.
256	        if (!householdMembers.isEmpty() && !sharesHousehold && !hasEmail) {
257	            return new ResponseEntity<>(HttpStatus.CONFLICT);
258	        }
259	        // Level ceiling: an owner admitted into an already-populated household without declaring
260	        // membership has its membership level capped at one above the household's current maximum, so
261	        // an undeclared newcomer can never outrank the household it joined. Declared members and
262	        // household founders are left uncapped. With no existing household member no cap applies.
263	        if (!householdMembers.isEmpty() && !sharesHousehold) {
264	            int maxHouseholdLevel = householdMembers.stream()
265	                .mapToInt(Owner::getMembershipLevel)
266	                .max()
267	                .orElse(0);
268	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
269	        }
270	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
271	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
272	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
273	        // telephone is part of the key, two household members with different telephones are allowed.
274	        // This still catches a full identity repeat even when it declares sharesHousehold.
275	        String identityKey = owner.getIdentityKey();
276	        boolean identityInUse = this.clinicService.findAllOwners().stream()
277	            .filter(existing -> !existing.getDeleted())
278	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
279	        if (identityInUse) {
280	            return new ResponseEntity<>(HttpStatus.CONFLICT);
281	        }
282	        // Soft-duplicate detection. A declared household member (sharesHousehold) is never a suspected
283	        // duplicate. Any other owner sharing an existing owner's last name and postcode with a
284	        // different telephone is now, by definition, a household duplicate already rejected above, so
285	        // it never reaches this point; the check is retained for owners that are not household matches.
286	        if (sharesHousehold) {
287	            owner.setPossibleDuplicate(false);
288	        } else {
