383	    /**
384	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
385	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
386	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
387	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
388	     * recognised country codes the national number (the digits after the country code) must also be
389	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
390	     * needs 10); a wrong national-number length yields {@code null}.
391	     *
392	     * @param telephone the raw telephone value (may be {@code null})
393	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
394	     *         a valid E.164 number
395	     */
396	    private String toE164(String telephone) {
397	        if (telephone == null) {
398	            return null;
399	        }
400	        String trimmed = telephone.trim();
401	        boolean hasCountryCode = trimmed.startsWith("+");
402	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
403	        if (hasCountryCode) {
404	            cleaned = cleaned.substring(1);
405	        }
406	        if (!cleaned.matches("[0-9]+")) {
407	            return null;
408	        }
409	        String digits;
410	        if (hasCountryCode) {
411	            digits = cleaned;
412	        } else {
413	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
414	            digits = "61" + national;
415	        }
416	        if (digits.length() < 8 || digits.length() > 15) {
417	            return null;
418	        }
419	        if (!hasValidNationalNumberLength(digits)) {
420	            return null;
421	        }
422	        return "+" + digits;
423	    }
