425	    /**
426	     * Checks the national-number length of an E.164 digit string (country code plus national
427	     * number, without the leading {@code '+'}) against its country code. When the number's country
428	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
429	     * country code must number exactly what that country requires; the longest matching country
430	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
431	     * only by the generic total-length rule).
432	     *
433	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
434	     * @return {@code true} if the national-number length is acceptable for the country code
435	     */
436	    private boolean hasValidNationalNumberLength(String digits) {
437	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
438	            .filter(entry -> digits.startsWith(entry.getKey()))
439	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
440	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
441	            .orElse(true);
442	    }
