471	    /**
472	     * Applies the owner's address, preferring the structured form over the flat one. When a
473	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
474	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
475	     * non-blank {@code addressLine2} is present, by a single space and the normalized
476	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
477	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
478	     * is invalid.
479	     *
480	     * @param owner the owner whose address fields are normalized and composed in place
481	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
482	     */
483	    private boolean applyAddress(Owner owner) {
484	        String line1 = owner.getAddressLine1();
485	        if (line1 != null && !line1.isBlank()) {
486	            String normalizedLine1 = normalizeAddress(line1);
487	            owner.setAddressLine1(normalizedLine1);
488	            String composed = normalizedLine1;
489	            String line2 = owner.getAddressLine2();
490	            if (line2 != null && !line2.isBlank()) {
491	                String normalizedLine2 = normalizeAddress(line2);
492	                owner.setAddressLine2(normalizedLine2);
493	                composed = normalizedLine1 + " " + normalizedLine2;
494	            }
495	            owner.setAddress(composed);
496	            return true;
497	        }
498	        String address = normalizeAddress(owner.getAddress());
499	        if (address == null || address.isEmpty()) {
500	            return false;
501	        }
502	        owner.setAddress(address);
503	        return true;
504	    }
