506	    /**
507	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
508	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
509	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
510	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
511	     * normalized form, and every household comparison uses it.
512	     *
513	     * @param address the raw address value (may be {@code null})
514	     * @return the normalized address, or {@code null} if the input was {@code null}
515	     */
516	    private String normalizeAddress(String address) {
517	        if (address == null) {
518	            return null;
519	        }
520	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
521	        if (collapsed.isEmpty()) {
522	            return collapsed;
523	        }
524	        String[] tokens = collapsed.split(" ");
525	        StringBuilder sb = new StringBuilder(collapsed.length());
526	        for (int i = 0; i < tokens.length; i++) {
527	            if (i > 0) {
528	                sb.append(' ');
529	            }
530	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
531	        }
532	        return sb.toString();
533	    }
