535	    /**
536	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
537	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
538	     * so that owners are compared case-insensitively with collapsed whitespace.
539	     *
540	     * @param value the raw value (must not be {@code null})
541	     * @return the normalized comparison key
542	     */
543	    private String householdKey(String value) {
544	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
