547	    /**
548	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
549	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
550	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
551	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
552	     * those two fields derives the identical identifier and therefore belongs to the same household.
553	     *
554	     * @param owner the owner whose household identifier is derived
555	     * @return the stable household identifier
556	     */
557	    private String householdId(Owner owner) {
558	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
559	        String key = householdKey(owner.getLastName()) + "|" + postcode;
560	        try {
561	            byte[] digest = MessageDigest.getInstance("SHA-256")
562	                .digest(key.getBytes(StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder(digest.length * 2);
564	            for (byte b : digest) {
565	                sb.append(String.format("%02x", b));
566	            }
567	            return sb.substring(0, 12);
568	        }
569	        catch (java.security.NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 not available", e);
571	        }
572	    }
