574	    /**
575	     * Builds the customer code for a newly registered owner in the form
576	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
577	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
578	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
579	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
580	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
581	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
582	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
583	     * always receive distinct customer codes.
584	     *
585	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
586	     * @return the assigned customer code
587	     */
588	    private String customerCode(Owner owner) {
589	        String region = owner.getLocality();
590	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
591	        String base = region + "-" + hash8;
592	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
593	            .map(Owner::getCustomerCode)
594	            .filter(code -> code != null)
595	            .collect(Collectors.toSet());
596	        if (!existingCodes.contains(base)) {
597	            return base;
598	        }
599	        int n = 2;
600	        while (existingCodes.contains(base + "-" + n)) {
601	            n++;
602	        }
603	        return base + "-" + n;
604	    }
605	
606	    /**
607	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
608	     * UTF-8 bytes of {@code input}.
609	     *
610	     * @param input  the value to hash
611	     * @param length the number of leading hex characters to keep
612	     * @return the truncated, upper-cased hex digest
613	     */
614	    private String sha256UpperHex(String input, int length) {
615	        try {
616	            byte[] digest = MessageDigest.getInstance("SHA-256")
617	                .digest(input.getBytes(StandardCharsets.UTF_8));
618	            StringBuilder sb = new StringBuilder(digest.length * 2);
619	            for (byte b : digest) {
620	                sb.append(String.format("%02x", b));
621	            }
622	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
623	        }
624	        catch (java.security.NoSuchAlgorithmException e) {
625	            throw new IllegalStateException("SHA-256 not available", e);
626	        }
627	    }
