630	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
631	        LocalDate.parse("2026-01-01"),
632	        LocalDate.parse("2026-01-26"),
633	        LocalDate.parse("2026-04-25"),
634	        LocalDate.parse("2026-12-25"),
