637	    /**
638	     * Rolls a registration date forward onto a business day. When the given date falls on a
639	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
640	     * lands on a non-holiday weekday; a business day is returned unchanged.
641	     *
642	     * @param date the effective registration date (must not be {@code null})
643	     * @return the same date if it is already a business day, otherwise the next business day
644	     */
645	    private LocalDate toBusinessDay(LocalDate date) {
646	        while (isNonBusinessDay(date)) {
647	            date = date.plusDays(1);
648	        }
649	        return date;
650	    }
651	
652	    private boolean isNonBusinessDay(LocalDate date) {
653	        DayOfWeek dayOfWeek = date.getDayOfWeek();
654	        return dayOfWeek == DayOfWeek.SATURDAY
655	            || dayOfWeek == DayOfWeek.SUNDAY
656	            || PUBLIC_HOLIDAYS.contains(date);
657	    }
